SourceCode.Declaration:
/// <summary>
/// Defines the number sequence module for the sales order management module.
/// </summary>
internal final class SNumberSeqModule extends NumberSeqApplicationModule
{
}

Method.Source:
/// <summary>
/// Loads the number sequence references for the order module.
/// </summary>
public void loadModule()
{
    NumberSeqDatatype datatype;

    datatype = NumberSeqDatatype::construct();

    datatype.parmDatatypeId(extendedTypeNum(SOrderID));
    datatype.parmReferenceHelp("@SLabels:SOrderID");
    datatype.parmWizardIsContinuous(false);
    datatype.parmWizardIsManual(NoYes::No);
    datatype.parmWizardIsChangeDownAllowed(NoYes::No);
    datatype.parmWizardIsChangeUpAllowed(NoYes::No);
    datatype.parmSortField(1);

    this.create(datatype);
}

/// <summary>
/// Returns the module identifier.
/// </summary>
/// <returns>
/// The sales order number sequence module identifier.
/// </returns>
public NumberSeqModule numberSeqModule()
{
    return NumberSeqModule::SOrder;
}
